"""Check the structural limits of the Sha'ar Stack project.

Rules (CLAUDE.md):
1. At most 700 lines per code file.
2. At most 7 directly nested items (files + subdirectories) in each
   directory, per git tracked paths.
3. unsafe policy: every workspace-package target (all kinds: lib, bin,
   test, example, bench, custom-build, proc-macro) must have EXACTLY
   #![forbid(unsafe_code)] as its FIRST physical line; crates/shaar-ygg
   packages must have exactly #![deny(unsafe_code)].

Code extensions (subject to the line limit):
    .rs, .go, .py, .sh, .bash, .ps1, .toml, .yml, .yaml
Boundary decisions:
    - Cargo.toml counts as code (build configuration).
    - Cargo.lock is not code (generated file); the line limit does not apply.
    - .yml/.yaml (including .github/workflows) count as code.
    - ONLY Markdown files (.md) are excluded from the line limit: docs
      with inline examples are not subject to the limit. Standalone code
      (e.g. docs/tool.py) is checked on the same terms.
    - No exceptions for guard fixtures: tracked fixtures are part of the
      project and obey the same limits (there are no oversized fixtures
      in the repo; boundaries are generated by tests in temp dirs).

Root targets: the source of truth is `cargo metadata --no-deps
--format-version 1 --locked --offline`; the toolchain is set by
RUSTUP_TOOLCHAIN in CI. Only packages from workspace_members are
checked (third-party ones are ignored). src_path is normalized via
Path.resolve + relative_to(root): ./, .., symlink parents and the drive
are taken into account; a target outside the root or not in the tracked
set is an explicit error. A file Cargo does not consider a target (e.g.
build.rs without a declaration) is not a root and requires no attribute.

Canonical placement of the unsafe attribute (deliberately simple
project contract, NOT full Rust parsing): the exact required attribute
must sit on the FIRST physical line of the file (a UTF-8 BOM is allowed
before it, no whitespace); after stripping the BOM and the line ending,
the line must equal exactly the attribute bytes. The primary enforcement
remains with rustc (forbid/deny); the script is a structural guard for
early failure in CI.

Readability (preflight): every non-service tracked file must be readable
(streamed, 64KB chunks, nothing stored). Order in main: readable ->
line/item limits -> metadata -> unsafe: on read violations metadata is
not invoked. Containment: a path is opened only if its resolve lies
inside realpath(root); this protects against static symlinks in the
checkout, but against a hostile concurrently mutable filesystem the
realpath+open pair is not race-free -- no full protection is claimed.

Source of paths: `git ls-files -z` (bytes, split on \\0 -- safe for
spaces, Unicode and newlines in names). Service prefixes (.git/,
.claude/, .rush/, worktrees/, target/) are ignored.

Git and cargo runners are injected as main parameters -- tests substitute
them with fakes; cargo and git are not actually run by the guard locally.
Returns nonzero on any violation; fail-closed: nonzero cargo exit,
invalid JSON, unexpected schema or empty workspace are violations.
"""

from __future__ import annotations

import json
import subprocess
import sys
from collections import defaultdict
from pathlib import Path

MAX_LINES = 700
MAX_ITEMS = 7
CHUNK = 65536
BOM = b"\xef\xbb\xbf"
FORBID = b"#![forbid(unsafe_code)]"
DENY = b"#![deny(unsafe_code)]"
DENY_PACKAGE = "shaar-ygg"
IGNORED_PREFIXES = (b".git/", b".claude/", b".rush/", b"worktrees/", b"target/")
CODE_EXTS = frozenset(
    (b".rs", b".go", b".py", b".sh", b".bash", b".ps1", b".toml", b".yml", b".yaml")
)
DOC_EXTS = frozenset((b".md",))


def parse_ls_files(raw: bytes) -> list[bytes]:
    """Parse `git ls-files -z` output: NUL-separated paths."""
    return [p for p in raw.split(b"\0") if p]


def run_git_ls_files() -> subprocess.CompletedProcess:
    """Get the repository's tracked path list."""
    return subprocess.run(
        ["git", "ls-files", "-z"],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )


def run_cargo_metadata(root: Path) -> subprocess.CompletedProcess:
    """Workspace target data; cargo is invoked only in CI."""
    return subprocess.run(
        ["cargo", "metadata", "--no-deps", "--format-version", "1",
         "--locked", "--offline"],
        cwd=root,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )


def is_ignored(path: bytes) -> bool:
    """Service prefixes of tools and artifacts are not considered project."""
    return path.startswith(IGNORED_PREFIXES)


def ext(path: bytes) -> bytes:
    """Lowercase path extension (bytes)."""
    slash = path.rfind(b"/")
    dot = path.rfind(b".")
    if dot <= slash:
        return b""
    return path[dot:].lower()


def is_code(path: bytes) -> bool:
    """Code file by extension; only Markdown files are excluded."""
    if ext(path) in DOC_EXTS:
        return False
    return ext(path) in CODE_EXTS


def count_lines(data: bytes) -> int:
    """Line count; a nonempty file without a trailing newline is one line."""
    n = data.count(b"\n")
    if data and not data.endswith(b"\n"):
        n += 1
    return n


def _open_checked(root: Path, full: Path):
    """Validate the whole resolved path, then open the file."""
    try:
        full.resolve().relative_to(root.resolve())
    except (ValueError, RuntimeError) as exc:
        raise OSError(f"path outside the project tree or symlink loop: {full}") from exc
    return open(full, "rb")


def check_readable(root: Path, paths: list[bytes]) -> list[str]:
    """Preflight: every non-service tracked file must be readable."""
    errors: list[str] = []
    for path in paths:
        if is_ignored(path):
            continue
        full = root / path.decode("utf-8", "surrogateescape")
        try:
            with _open_checked(root, full) as fh:
                while fh.read(CHUNK):
                    pass
        except OSError as exc:
            errors.append(f"failed to read {path.decode('utf-8', 'replace')}: {exc}")
    return errors


def check_line_limits(root: Path, paths: list[bytes]) -> list[str]:
    """700-line limit per code file. A read error is a violation."""
    errors: list[str] = []
    for path in paths:
        if is_ignored(path) or not is_code(path):
            continue
        full = root / path.decode("utf-8", "surrogateescape")
        try:
            with _open_checked(root, full) as fh:
                lines = count_lines(fh.read())
        except OSError as exc:
            errors.append(f"failed to read {path.decode('utf-8', 'replace')}: {exc}")
            continue
        if lines > MAX_LINES:
            errors.append(
                f"{path.decode('utf-8', 'replace')}: {lines} lines (limit {MAX_LINES})"
            )
    return errors


def check_item_limits(paths: list[bytes]) -> list[str]:
    """7-item limit (files + subdirectories) per directory on tracked paths."""
    children: dict[bytes, set[bytes]] = defaultdict(set)
    for path in paths:
        if is_ignored(path):
            continue
        parts = path.split(b"/")
        # Every item, including a file, counts as an item of its directory.
        for i in range(len(parts)):
            parent = b"/".join(parts[:i])
            children[parent].add(parts[i])
    errors: list[str] = []
    for parent in sorted(children):
        n = len(children[parent])
        if n > MAX_ITEMS:
            name = parent.decode("utf-8", "replace") or "<repository root>"
            errors.append(f"{name}: {n} items (limit {MAX_ITEMS})")
    return errors


def parse_metadata(raw: bytes, root: Path, tracked: set[bytes]) -> tuple[list[tuple[bytes, str]], list[str]]:
    """Extract root targets of workspace packages: [(path, package name)].

    Fail-closed: invalid JSON, unexpected schema, a target outside the
    root or outside the tracked set are errors, not skips.
    """
    errors: list[str] = []
    try:
        cfg = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        return [], [f"cargo metadata: invalid JSON: {exc}"]
    if not isinstance(cfg, dict):
        return [], ["cargo metadata: unexpected schema (root is not an object)"]
    members = cfg.get("workspace_members")
    packages = cfg.get("packages")
    if not isinstance(members, list) or not isinstance(packages, list):
        return [], ["cargo metadata: unexpected schema (no workspace_members/packages)"]
    if not members:
        return [], ["cargo metadata: empty workspace"]
    if any(not isinstance(member, str) or not member for member in members):
        return [], ["cargo metadata: invalid workspace member IDs"]
    member_ids = set(members)
    if len(member_ids) != len(members):
        return [], ["cargo metadata: duplicate workspace member IDs"]
    root_real = root.resolve()
    found_members: set[str] = set()
    targets: list[tuple[bytes, str]] = []

    def relative_path(value: str) -> Path:
        path = Path(value)
        if not path.is_absolute():
            path = root_real / path
        return path.resolve().relative_to(root_real)

    for package in packages:
        if (not isinstance(package, dict)
                or not isinstance(package.get("id"), str) or not package["id"]):
            errors.append("cargo metadata: invalid package or package ID")
            continue
        package_id = package["id"]
        if package_id not in member_ids:
            continue
        if package_id in found_members:
            errors.append(f"cargo metadata: duplicate package {package_id}")
            continue
        found_members.add(package_id)
        name = package.get("name")
        manifest = package.get("manifest_path")
        package_targets = package.get("targets")
        if (not isinstance(name, str) or not name
                or not isinstance(manifest, str) or not manifest
                or not isinstance(package_targets, list)):
            errors.append(f"cargo metadata: unexpected package schema for {package_id}")
            continue
        try:
            relative_path(manifest)
        except (OSError, ValueError, RuntimeError):
            errors.append(f"cargo metadata: manifest of package {name} outside the project root")
            continue
        if not package_targets:
            errors.append(f"cargo metadata: package {name} has no targets")
            continue
        for target in package_targets:
            if not isinstance(target, dict):
                errors.append(f"cargo metadata: target of package {name} is not an object")
                continue
            source = target.get("src_path")
            kinds = target.get("kind")
            if (not isinstance(source, str) or not source
                    or not isinstance(kinds, list) or not kinds
                    or any(not isinstance(kind, str) or not kind for kind in kinds)):
                errors.append(f"cargo metadata: unexpected target schema for package {name}")
                continue
            try:
                relative = relative_path(source)
            except (OSError, ValueError, RuntimeError):
                errors.append(f"cargo metadata: target of package {name} outside the project root")
                continue
            relative_bytes = relative.as_posix().encode("utf-8", "surrogateescape")
            if relative_bytes not in tracked or is_ignored(relative_bytes):
                errors.append(
                    f"cargo metadata: target of package {name} is not a tracked project "
                    f"file: {relative.as_posix()}"
                )
                continue
            targets.append((relative_bytes, name))
    missing = member_ids - found_members
    if missing:
        errors.append(f"cargo metadata: workspace members without packages: {sorted(missing)}")
    if not targets and not errors:
        errors.append("cargo metadata: no workspace targets")
    return targets, errors


def check_unsafe_policy(root: Path, targets: list[tuple[bytes, str]]) -> list[str]:
    """First line of each target must be exactly the required unsafe attribute."""
    errors: list[str] = []
    for path, package in targets:
        expected = DENY if package == DENY_PACKAGE else FORBID
        full = root / path.decode("utf-8", "surrogateescape")
        try:
            with _open_checked(root, full) as fh:
                first = fh.readline()
        except OSError as exc:
            errors.append(f"failed to read {path.decode('utf-8', 'replace')}: {exc}")
            continue
        if first.startswith(BOM):
            first = first[len(BOM):]
        if first.rstrip(b"\r\n") != expected:
            found = first.rstrip(b"\r\n").decode("utf-8", "replace")
            errors.append(
                f"{path.decode('utf-8', 'replace')}: first line {found!r}, "
                f"expected exactly {expected.decode()}"
            )
    return errors


def main(runner=run_git_ls_files, metadata=run_cargo_metadata, root: Path | None = None) -> int:
    """Entry point: git tracked paths, then checks; metadata after preflight."""
    root = Path.cwd() if root is None else root
    try:
        proc = runner()
    except OSError as exc:
        print(f"error starting git: {exc}", file=sys.stderr)
        return 1
    if proc.returncode != 0:
        stderr = proc.stderr.decode("utf-8", "replace").strip()
        print(f"git ls-files failed: {stderr}", file=sys.stderr)
        return 1
    paths = parse_ls_files(proc.stdout)
    errors = check_readable(root, paths)
    if errors:
        # Preflight: read nothing further if the tree is not fully readable.
        for err in errors:
            print(f"VIOLATION: {err}", file=sys.stderr)
        print(f"Total violations: {len(errors)}", file=sys.stderr)
        return 1
    errors += check_line_limits(root, paths)
    errors += check_item_limits(paths)
    try:
        meta = metadata(root)
    except OSError as exc:
        print(f"error starting cargo metadata: {exc}", file=sys.stderr)
        return 1
    if meta.returncode != 0:
        stderr = meta.stderr.decode("utf-8", "replace").strip()
        print(f"cargo metadata failed: {stderr}", file=sys.stderr)
        return 1
    targets, meta_errors = parse_metadata(meta.stdout, root, set(paths))
    errors += meta_errors
    errors += check_unsafe_policy(root, targets)
    if errors:
        for err in errors:
            print(f"VIOLATION: {err}", file=sys.stderr)
        print(f"Total violations: {len(errors)}", file=sys.stderr)
        return 1
    print(f"OK: {len(paths)} tracked paths, structural limits hold.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
